<!doctype html><html><head><style>body{font-family:DejaVu Sans;font-size:11px;color:#222}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #555;padding:7px}th{background:#eee}.num{text-align:right}</style></head><body><h1>Indus Gas — Ledger Report</h1><p><b>Customer:</b> {{ $customer->title }}<br><b>Phone:</b> {{ $customer->phone }}</p><table><thead><tr><th>Date</th><th>Description</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Balance</th></tr></thead><tbody>@php($balance=0)@foreach($entries as $entry)@php($balance+=$entry['debit']-$entry['credit'])<tr><td>{{ $entry['date']->format('d-m-Y') }}</td><td>{{ $entry['description'] }}</td><td class="num">{{ $entry['debit'] ? number_format($entry['debit'],2) : '' }}</td><td class="num">{{ $entry['credit'] ? number_format($entry['credit'],2) : '' }}</td><td class="num">{{ number_format($balance,2) }}</td></tr>@endforeach</tbody></table></body></html>
